import{_ as a,o as t,c as i,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy team hub","description":"<!-- impeccable:product-schema 1 -->","frontmatter":{"title":"Chainy team hub","description":"<!-- impeccable:product-schema 1 -->","source":"PRODUCT.md","category":"Other documents","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/product.md","filePath":"content/product.md"}'),n={name:"content/product.md"};function s(o,e,c,d,h,l){return t(),i("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-team-hub">Chainy team hub<a class="header-anchor" href="#chainy-team-hub" aria-label="Link to this section">​</a></h1><p>&lt;!-- impeccable:product-schema 1 --&gt;</p><h2 id="platform">Platform<a class="header-anchor" href="#platform" aria-label="Link to this section">​</a></h2><p>web</p><h2 id="users">Users<a class="header-anchor" href="#users" aria-label="Link to this section">​</a></h2><p>Five capstone teammates: Sherwin (Project and Design), Christian (Tech), Luis (Art), Sean (Docs), and Miguel (UI). Project-management vocabulary should suit beginner to intermediate readers.</p><h2 id="product-purpose">Product Purpose<a class="header-anchor" href="#product-purpose" aria-label="Link to this section">​</a></h2><p>Read the current project documentation, choose assigned work, move cards, adjust the schedule and see who changed a task. The user requested familiar Trello-style interaction with clear task names instead of visible task codes.</p><h2 id="operating-context">Operating Context<a class="header-anchor" href="#operating-context" aria-label="Link to this section">​</a></h2><p>The existing GitHub Pages documentation site and Cloudflare Worker provide the hosting foundation. Five individual username/password accounts share one board. Trello is disconnected. GitHub issues retain the execution record; the team board is the editing interface. The game itself remains offline and independent of this management service.</p><h2 id="capabilities-and-constraints">Capabilities and Constraints<a class="header-anchor" href="#capabilities-and-constraints" aria-label="Link to this section">​</a></h2><p>All five members can create, read, edit, move and delete cards. History records actor, change, surface and server time. Kanban and Gantt use the same saved tasks. Beta is November 10, 2026 — Cryptita Plays community beta testing; pre-final is November 21, 2026. GDD v2 governs the core restoration/record-repair chapter; standalone Wordle and BlockMatch are deferred. Preserve existing issue links and avoid duplicate tasks. Credentials and participant records must never enter published files.</p><h2 id="evidence-on-hand">Evidence on Hand<a class="header-anchor" href="#evidence-on-hand" aria-label="Link to this section">​</a></h2><p>The canonical GDD, technical addendum, role plan and publication snapshot are in docs/. The live board is authoritative for task status, ownership and named history; local historical counts are not current progress. No task completion is inferred from component reports.</p><h2 id="product-principles">Product Principles<a class="header-anchor" href="#product-principles" aria-label="Link to this section">​</a></h2><ul><li>Use names and visible states, with technical identifiers kept behind the interface.</li><li>Save shared changes before reporting success.</li><li>Preserve history and offer recovery from deletion.</li><li>Keep fixed project events distinct from editable planning dates.</li></ul></div>',1)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
